import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';

/** A worker heartbeat older than this means the worker is down. */
export const HEARTBEAT_MAX_AGE_MS = 3_000;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

interface JobRow {
  seq: number;
  id: string;
  idempotency_key: string | null;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  next_attempt_at: number;
  lease_until: number | null;
  created_at: string;
  updated_at: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface ClaimedJob {
  id: string;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
}

export type SubmitResult = { kind: 'created' | 'replay'; job: Job } | { kind: 'conflict' };

function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function one(db: DatabaseSync, sql: string, params: (string | number | null)[]): JobRow | undefined {
  return db.prepare(sql).get(...params) as unknown as JobRow | undefined;
}

/**
 * Creates a job, or returns the existing one for a repeated idempotency key. The check and the
 * insert run in one immediate transaction so a key can never create two jobs.
 */
export function submitJob(db: DatabaseSync, job: NewJob, idempotencyKey: string | null): SubmitResult {
  db.exec('BEGIN IMMEDIATE');
  try {
    let result: SubmitResult;
    const existing = idempotencyKey === null ? undefined : one(db, 'SELECT * FROM jobs WHERE idempotency_key = ?', [idempotencyKey]);
    if (existing) {
      const same = existing.input === job.input && existing.steps === job.steps && existing.fail_attempts === job.failAttempts;
      result = same ? { kind: 'replay', job: toJob(existing) } : { kind: 'conflict' };
    } else {
      const id = randomUUID();
      const now = new Date().toISOString();
      db.prepare(
        `INSERT INTO jobs (id, idempotency_key, status, input, steps, fail_attempts, attempts, progress_completed,
                           next_attempt_at, created_at, updated_at)
         VALUES (?, ?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?)`,
      ).run(id, idempotencyKey, job.input, job.steps, job.failAttempts, now, now);
      result = { kind: 'created', job: toJob(one(db, 'SELECT * FROM jobs WHERE id = ?', [id])!) };
    }
    db.exec('COMMIT');
    return result;
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

export function getJob(db: DatabaseSync, id: string): Job | undefined {
  const row = one(db, 'SELECT * FROM jobs WHERE id = ?', [id]);
  return row && toJob(row);
}

export function listJobs(db: DatabaseSync): Job[] {
  return (db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[]).map(toJob);
}

/**
 * Claims the oldest job that is due: queued and past its retry time, or running under a lease that
 * has expired (its worker died). The claim starts a new attempt.
 */
export function claimNextJob(db: DatabaseSync, now: number, leaseMs: number): ClaimedJob | undefined {
  const row = db
    .prepare(
      `UPDATE jobs
          SET status = 'running', attempts = attempts + 1, progress_completed = 0,
              lease_until = ?, updated_at = ?
        WHERE seq = (SELECT seq FROM jobs
                      WHERE (status = 'queued' AND next_attempt_at <= ?)
                         OR (status = 'running' AND lease_until < ?)
                      ORDER BY seq ASC LIMIT 1)
    RETURNING id, input, steps, fail_attempts, attempts`,
    )
    .get(now + leaseMs, new Date(now).toISOString(), now, now) as
    | { id: string; input: string; steps: number; fail_attempts: number; attempts: number }
    | undefined;
  return row && { id: row.id, input: row.input, steps: row.steps, failAttempts: row.fail_attempts, attempts: row.attempts };
}

/** Records one finished step and renews the lease on the running attempt. */
export function recordProgress(db: DatabaseSync, id: string, completed: number, now: number, leaseMs: number): void {
  db.prepare('UPDATE jobs SET progress_completed = ?, lease_until = ?, updated_at = ? WHERE id = ?').run(
    completed,
    now + leaseMs,
    new Date(now).toISOString(),
    id,
  );
}

export function completeJob(db: DatabaseSync, id: string, output: string, steps: number, now: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', result_output = ?, error = NULL, progress_completed = ?,
                     lease_until = NULL, updated_at = ? WHERE id = ?`,
  ).run(output, steps, new Date(now).toISOString(), id);
}

export function failJob(db: DatabaseSync, id: string, error: string, now: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, progress_completed = 0,
                     lease_until = NULL, updated_at = ? WHERE id = ?`,
  ).run(error, new Date(now).toISOString(), id);
}

export function requeueJob(db: DatabaseSync, id: string, nextAttemptAt: number, now: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', progress_completed = 0, lease_until = NULL,
                     next_attempt_at = ?, updated_at = ? WHERE id = ?`,
  ).run(nextAttemptAt, new Date(now).toISOString(), id);
}

export function writeHeartbeat(db: DatabaseSync, now: number): void {
  db.prepare(
    `INSERT INTO worker_heartbeat (id, seen_at) VALUES (1, ?)
     ON CONFLICT (id) DO UPDATE SET seen_at = excluded.seen_at`,
  ).run(now);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare('DELETE FROM worker_heartbeat WHERE id = 1').run();
}

export function isWorkerUp(db: DatabaseSync, now: number): boolean {
  const row = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id = 1').get() as { seen_at: number } | undefined;
  return row !== undefined && now - row.seen_at <= HEARTBEAT_MAX_AGE_MS;
}

