import type { NewJob } from './jobs.ts';

export interface FieldError {
  field: string;
  message: string;
}

export type ParseResult = { ok: true; value: NewJob } | { ok: false; fields: FieldError[] };

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
const MAX_INPUT_LENGTH = 1000;

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isIntegerIn(value: unknown, min: number, max: number): boolean {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

/** Parses and validates a submission body. Defaults are applied to missing optional fields. */
export function parseSubmission(text: string): ParseResult {
  let body: unknown;
  try {
    body = JSON.parse(text);
  } catch {
    return { ok: false, fields: [{ field: 'body', message: 'body must be valid JSON' }] };
  }
  if (!isPlainObject(body)) {
    return { ok: false, fields: [{ field: 'body', message: 'body must be a JSON object' }] };
  }

  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  const { input, steps = 5, failAttempts = 0 } = body;
  if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'input is required and must be a string' });
  } else if (input.length < 1 || input.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `input must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (input.trim().length === 0) {
    fields.push({ field: 'input', message: 'input must not be only whitespace' });
  }
  if (!isIntegerIn(steps, 1, 20)) fields.push({ field: 'steps', message: 'steps must be an integer from 1 to 20' });
  if (!isIntegerIn(failAttempts, 0, 5)) {
    fields.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5' });
  }

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input: input as string, steps: steps as number, failAttempts: failAttempts as number } };
}

/** Returns an error if the Idempotency-Key header is present and malformed. */
export function checkIdempotencyKey(header: string | undefined): FieldError | null {
  if (header === undefined || IDEMPOTENCY_KEY.test(header)) return null;
  return { field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$' };
}

