input.content:
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { getJob, isWorkerUp, listJobs, submitJob, type Job, type NewJob } from './jobs.ts';
import { checkIdempotencyKey, parseSubmission, type FieldError } from './validation.ts';

const MAX_BODY_BYTES = 64 * 1024;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  sendJson(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

function invalid(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', 'The job submission is invalid.', fields);
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed for this path.', undefined);
  res.setHeader('allow', allow);
}

function mediaType(header: string | undefined): string {
  return (header ?? '').split(';')[0]!.trim().toLowerCase();
}

/** Reads the whole body. Resolves to null when it exceeds MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size <= MAX_BODY_BYTES) chunks.push(chunk);
    });
    req.on('end', () => resolve(size > MAX_BODY_BYTES ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const text = await readBody(req);
  const keyHeader = req.headers['idempotency-key'];
  const key = typeof keyHeader === 'string' ? keyHeader : undefined;

  const errors: FieldError[] = [];
  const keyError = checkIdempotencyKey(key);
  if (keyError) errors.push(keyError);

  let job: NewJob | undefined;
  if (mediaType(req.headers['content-type']) !== 'application/json') {
    errors.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (text === null) {
    errors.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    const parsed = parseSubmission(text);
    if (parsed.ok) job = parsed.value;
    else errors.push(...parsed.fields);
  }

  if (errors.length > 0 || job === undefined) {
    invalid(res, errors);
    return;
  }
  const outcome = submitJob(db, job, key ?? null);
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, outcome.job);
}

function handleGetJob(res: ServerResponse, id: string): void {
  const job: Job | undefined = getJob(db, id);
  if (!job) sendError(res, 404, 'not_found', 'No job with that id.');
  else sendJson(res, 200, job);
}

function handle(req: IncomingMessage, res: ServerResponse): void | Promise<void> {
  const method = req.method ?? 'GET';
  const isGet = method === 'GET' || method === 'HEAD';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') {
    if (!isGet) return methodNotAllowed(res, 'GET, HEAD');
    return sendJson(res, 200, { status: 'ok', worker: isWorkerUp(db, Date.now()) ? 'up' : 'down' });
  }
  if (pathname === '/') {
    if (!isGet) return methodNotAllowed(res, 'GET, HEAD');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'POST') return handleCreate(req, res);
    if (!isGet) return methodNotAllowed(res, 'GET, HEAD, POST');
    return sendJson(res, 200, { jobs: listJobs(db) });
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (!isGet) return methodNotAllowed(res, 'GET, HEAD');
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No job with that id.');
    }
    return handleGetJob(res, id);
  }
  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  Promise.resolve(handle(req, res)).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
  });
});

