import { setInterval as every, setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  claimNextJob,
  clearHeartbeat,
  completeJob,
  failJob,
  recordProgress,
  requeueJob,
  writeHeartbeat,
  type ClaimedJob,
} from './jobs.ts';
import type { DatabaseSync } from 'node:sqlite';

/** Time per step. */
const STEP_MS = 100;
/** Pause between polls when no job is due. */
const POLL_MS = 200;
/** How often the worker proves it is alive. */
const HEARTBEAT_MS = 1_000;
/** A running attempt whose lease is not renewed for this long is treated as abandoned. */
const LEASE_MS = 5_000;
/** Delay before a failed attempt is retried (between 250 ms and 2 s). */
const RETRY_DELAY_MS = 1_000;
/** Total attempts, including the first. */
const MAX_ATTEMPTS = 3;

const db = openDatabase();
let stopping = false;

function beat(): void {
  try {
    writeHeartbeat(db, Date.now());
  } catch (err) {
    console.error('heartbeat failed:', err);
  }
}

/** Runs one attempt. Returns early without recording anything if the worker is stopping. */
async function runAttempt(job: ClaimedJob): Promise<void> {
  const fails = job.attempts <= job.failAttempts;
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    if (step === 1 && fails) {
      if (job.attempts >= MAX_ATTEMPTS) {
        failJob(db, job.id, 'transient failure', Date.now());
      } else {
        requeueJob(db, job.id, Date.now() + RETRY_DELAY_MS, Date.now());
      }
      return;
    }
    recordProgress(db, job.id, step, Date.now(), LEASE_MS);
  }
  completeJob(db, job.id, job.input.toUpperCase(), job.steps, Date.now());
}

async function main(): Promise<void> {
  beat();
  // Heartbeats run on their own timer so they continue while a long job is in progress.
  const heartbeat = setInterval(beat, HEARTBEAT_MS);

  for (const signal of ['SIGINT', 'SIGTERM'] as const) {
    process.on(signal, () => {
      stopping = true;
    });
  }

  console.log('worker started');
  while (!stopping) {
    let job: ClaimedJob | undefined;
    try {
      job = claimNextJob(db, Date.now(), LEASE_MS);
    } catch (err) {
      console.error('claim failed:', err);
    }
    if (!job) {
      await sleep(POLL_MS);
      continue;
    }
    try {
      await runAttempt(job);
    } catch (err) {
      // Leave the job running; its lease expires and it is claimed again.
      console.error(`attempt on job ${job.id} failed:`, err);
    }
  }

  clearInterval(heartbeat);
  try {
    clearHeartbeat(db);
  } catch {
    // The heartbeat expires on its own within 3 seconds.
  }
  db.close();
  console.log('worker stopped');
}

void every;
await main();
process.exit(0);

